import { GRUtils } from './utils/GRUtils';
import gsap from 'gsap';
import { SpinProfileAction } from './core/values/SpinProfileAction';
import { GRServiceEvent, ICoreSettings, IGenericReelCommands, IReelSettings, IReelSpeedConfig, ISymbolSettings, RegisterResponse, SpinState } from '../types';
import { GRModel } from './core/model/GRModel';
import { GRSettings } from './core/model/GRSettings';
import { GREvents } from '../events';
import { SpinProfileSequence } from './core/values/SpinProfileSequence';
export class GRService {

    public readonly eventFire: GRServiceEvent;

    public readonly commands: IGenericReelCommands = {
        // used by the package.
        stepSpinSequence: () => this.stepSpinSequence(),
        registerReel: (reelIndex: number) => this.registerReel(reelIndex)
    };

    protected _registeredReels: number[] = [];
    protected _model: GRModel;
    protected _settings: GRSettings;
    protected _events: GREvents;

    private _currentSpinProfile: SpinProfileAction[] = [];
    private _defaultSpinProfile: SpinProfileAction[] = [];
    private _spinSequenceProgress: number = 0;

    constructor() {
        this._settings = new GRSettings();
        this._events = new GREvents();
        this._model = new GRModel(this);

        this.eventFire = { serviceEvent: this._events.serviceEvents };
    }

    public runSpinSequence(): void {
        // set all states to spinning.
        const sequenceLength = this._registeredReels.length;
        this._model.spinComplete = false;
        this._model.spinState = GRUtils.buildNumberArray(sequenceLength, SpinState.SPINNING);
        this._spinSequenceProgress = 0;

        // generate and format spin profile.
        this._currentSpinProfile = this.formatSequence(this.spinProfile.sequence);

        // set reel speed from sequence action.
        this._model.spinSpeedValues = this.getReelSpeedsForCurrentSpin();

        // call next step in sequence after current sequence delay.
        gsap.delayedCall(this._currentSpinProfile[this._spinSequenceProgress].delay, this.executeCurrentSequenceAction.bind(this));
    }

    public setSpinSequence(endPositions: number[], startPositions?: number[]): void {

        // startPositions will be an array with each reels start index
        if (startPositions) {
            this.model.startPosition = startPositions;
        }
        /*
            e.g [10, 22, 44, 5] - this would represent the startPositions of a 4 x ? slot.
        */

        // removalLocations is a 2d array containing symbols that need to be removed. 
        this.model.targetPosition = endPositions;
        /* 
            e.g [15, 27, 49, 11] - this would represent the endPositions of a 4 x ? slot.
        */
    }

    private stepSpinSequence(): void {
        // increment sequence step and fire event.
        this._spinSequenceProgress++;
        this.eventFire.serviceEvent.ON_SEQUENCE_STEP();

        // check if full sequence has been complete.
        if (this._spinSequenceProgress === this._currentSpinProfile.length) {
            this.sequenceComplete();
            return;
        }
        const spinAction: SpinProfileAction = this._currentSpinProfile[this._spinSequenceProgress];
        if (spinAction.stopReel === -1) {
            return;
        }
        // set reel speed from sequence action.
        this._model.spinSpeedValues = this.getReelSpeedsForCurrentSpin();

        gsap.delayedCall(spinAction.delay, this.executeCurrentSequenceAction.bind(this));
    }

    private registerReel(reelIndex: number): RegisterResponse {
        // register unique id.
        if (this._registeredReels.indexOf(reelIndex) !== -1) {
            console.warn('A reel has already been registered using this index id.');
            return { success: false };
        }
        this._registeredReels.push(reelIndex);

        // create default data.
        this._defaultSpinProfile.push(new SpinProfileAction(this._registeredReels.length, 45, 0.15));
        this._model.startPosition.push(0);
        if (this._model.onScreenReels[reelIndex] !== undefined) {
            return { success: true };
        }

        //create dummy reel data.
        const dummyReel: number[][] = GRUtils.generateAllDummyReels(4, 5, GRUtils.buildNumberArray(this._registeredReels.length, 41));
        this._model.onScreenReels[reelIndex] = dummyReel[reelIndex];
        console.warn('A reel has been generated with dummy data.');
        return { success: true };
    }

    private executeCurrentSequenceAction(): void {
        // get stop data from current spin action.
        const currentSpinAction: SpinProfileAction = this._currentSpinProfile[this._spinSequenceProgress];
        const spinStopData: number | number[] = currentSpinAction.stopReel;

        // create template of model spinState.
        const newSpinState: number[] = [...this._model.spinState];

        // check and update if spinStopData has simultaneous stops.
        if (Array.isArray(spinStopData)) {
            for (const $targetReel of spinStopData) {
                newSpinState[$targetReel - 1] = SpinState.STOPPED;
            }
            this._model.spinState = newSpinState;
            return;
        }

        // else just update the single stop.
        newSpinState[spinStopData - 1] = SpinState.STOPPED;
        this._model.spinState = newSpinState;
    }

    private formatSequence(spinSequence: SpinProfileAction[]): SpinProfileAction[] {
        // format the sequence for arrayed stops
        const formattedSequence: SpinProfileAction[] = spinSequence.flatMap((action) => {
            if (Array.isArray(action.stopReel)) {
                // Exclude the last element from stopReel when creating dummy actions
                const dummyActions = action.stopReel.slice(0, -1).map(() => new SpinProfileAction(-1, -1, -1));
                return [action, ...dummyActions];
            }
            return [action];
        });

        return formattedSequence;
    }

    private getReelSpeedsForCurrentSpin(): Array<number> {
        // Get the sequence length and the current spin profile configuration
        const sequenceLength = this._registeredReels.length;
        const spinProfile = this._currentSpinProfile[this._spinSequenceProgress];
        const reelSpeedConfig = spinProfile.reelSpeed;

        // Check the type of reelSpeedConfig and process accordingly
        switch (typeof reelSpeedConfig) {
            case 'object':
                // If reelSpeedConfig is an array, return it directly
                if (Array.isArray(reelSpeedConfig)) {
                    return reelSpeedConfig;
                } else if ('speed' in reelSpeedConfig) {
                    // If reelSpeedConfig is an IReelSpeedConfig object, process the speed and optional overrides
                    const config = reelSpeedConfig as IReelSpeedConfig;
                    const globalSpeed = config.speed;
                    const overrides = config.overrides;
                    const reelSpeeds = new Array<number>(sequenceLength).fill(globalSpeed);

                    // Apply overrides to the corresponding reel speeds, if provided
                    if (overrides) {
                        for (const [reelIndex, speed] of Object.entries(overrides)) {
                            reelSpeeds[parseInt(reelIndex) - 1] = speed;
                        }
                    }
                    return reelSpeeds;
                } else {
                    // If reelSpeedConfig has an invalid object structure, throw an error
                    throw new Error(`Invalid reelSpeedConfig object: ${JSON.stringify(reelSpeedConfig)}`);
                }
            case 'number':
                // If reelSpeedConfig is a number, create an array of that length and fill it with the value
                return new Array(sequenceLength).fill(reelSpeedConfig);
            default:
                // If reelSpeedConfig has an invalid type, throw an error
                throw new Error(`Invalid reelSpeedConfig type: ${typeof reelSpeedConfig}`);
        }
    }

    private sequenceComplete(): void {
        this._model.spinComplete = true;
        this.eventFire.serviceEvent.ON_SPIN_COMPLETE();
    }

    public get model(): GRModel {
        return this._model;
    }

    public get coreSettings(): ICoreSettings {
        return this._settings.coreSettings;
    }

    public set coreSettings(settings: ICoreSettings | Partial<ICoreSettings>) {
        this._settings.updateCoreSettings(settings);
    }

    public get symbolSettings(): ISymbolSettings {
        return this._settings.symbolSettings;
    }

    public set symbolSettings(settings: ISymbolSettings | Partial<ISymbolSettings>) {
        this._settings.updateSymbolSettings(settings);
    }

    public get reelSettings(): IReelSettings {
        return this._settings.reelSettings;
    }

    public set reelSettings(settings: IReelSettings | Partial<IReelSettings>) {
        this._settings.updateReelSettings(settings);
    }

    public get spinProfile(): SpinProfileSequence {
        return this._model.selectedSpinProfileSequence ?? new SpinProfileSequence(this._defaultSpinProfile);
    }

    public set spinProfile(spinProfileSequence: SpinProfileSequence) {
        // spinProfileSequence is an array of spinProfileActions.
        this.model.selectedSpinProfileSequence = spinProfileSequence;
        /* 
            e.g [new SpinProfileAction(1, 45, 2), new SpinProfileAction(2, 45, 0.75), new SpinProfileAction(3, 45, 0.75)] - this would represent a spinProfileSequence of a 3 x ? slot.
        */
    }

}

